         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array[]} an array of objects representing market data
         */
        $type = $this->safe_string($params, 'type', 'spot');
        $request = $this->omit($params, array( 'type' ));
        if ($type === 'otc') {
            $cumulativeResponse = $this->publicGetV1MarketPairsCumulative ($request);
            return $this->parse_cumulative_markets($cumulativeResponse);
        }
        $response = $this->publicGetV1MarketPairsPricing ($request);
        return $this->parse_markets($response);
    }

    public function parse_ticker($ticker, ?array $market = null): array {
        $bid = $this->safe_list($ticker, 'bid', array());
        $ask = $this->safe_list($ticker, 'ask', array());
        $nestedOrderBook = $this->safe_dict($ticker, 'orderBook');
        $cumulativeOrderBook = $nestedOrderBook;
        if (($nestedOrderBook === null) && ($this->safe_string($ticker, 'bestBid') !== null)) {
            $cumulativeOrderBook = $ticker;
