    public function fetch_tickers(?array $symbols = null, $params = array ()): array {
        /**
         * fetches price tickers for multiple markets
         * @see https://api.asacoine.com/api/v1/market/pairs/pricing
         * @param {string[]|null} $symbols unified $symbols of the markets to fetch the tickers for, all $market tickers are returned if not assigned
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a dictionary of ~@link https://docs.ccxt.com/#/?id=$ticker-structure $ticker structures~
         */
        $type = $this->safe_string($params, 'type', 'spot');
        $request = $this->omit($params, array( 'type' ));
        $this->load_markets(false, array( 'type' => $type ));
        if ($symbols !== null) {
            $symbols = $this->market_symbols($symbols);
        }
        $response = array();
        if ($type === 'otc') {
            $response = $this->publicGetV1MarketPairsCumulative ($request);
        } else {
            $response = $this->publicGetV1MarketPairsPricing ($request);
        }
        if ($type === 'otc') {
            $cumulativeData = $this->safe_dict($response, 'data', array());
            $keys = $this->safe_list($cumulativeData, 'keys', array());
            $values = $this->safe_list($cumulativeData, 'values', array());
            $cumulativeTickers = array();
            for ($i = 0; $i < count($values); $i++) {
                $row = $values[$i];
                $raw = array();
                for ($j = 0; $j < count($keys); $j++) {
                    $raw[$keys[$j]] = $row[$j];
                }
                $name = $this->safe_string($raw, 'name');
                list($baseId, $quoteId) = explode('-', $name);
                $base = $this->safe_currency_code($baseId);
                $quote = $this->safe_currency_code($quoteId);
                $market = $this->safe_market($base . '/' . $quote);
                $parsed = $this->parse_ticker($this->safe_dict($raw, 'orderBook', array()), $market);
                $cumulativeTickers[$parsed['symbol']] = $parsed;
            }
            return $this->filter_by_array_tickers($cumulativeTickers, 'symbol', $symbols);
        }
        $data = $this->safe_dict($response, 'data', array());
        $baseIds = is_array($data) ? array_keys($data) : array();
        $result = array();
        for ($i = 0; $i < count($baseIds); $i++) {
            $baseId = $baseIds[$i];
            $quotes = $this->safe_dict($data, $baseId, array());
            $quoteIds = is_array($quotes) ? array_keys($quotes) : array();
            for ($j = 0; $j < count($quoteIds); $j++) {
                $quoteId = $quoteIds[$j];
                $ticker = $this->safe_dict($quotes, $quoteId, array());
                $market = $this->safe_market($baseId . '/' . $quoteId);
                $parsed = $this->parse_ticker($ticker, $market);
                $result[$parsed['symbol']] = $parsed;
            }
        }
        return $this->filter_by_array_tickers($result, 'symbol', $symbols);
    }

